import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const h=JSON.parse('{"title":"Chainy technical design","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","frontmatter":{"title":"Chainy technical design","description":"Capstone project title: Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain & AI)","source":"docs/technical-design.md","category":"Game & system design","sourceUpdated":"2026-10-08T07:30:14+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/technical-design.md","filePath":"content/docs/technical-design.md"}'),r={name:"content/docs/technical-design.md"};function s(o,e,d,c,l,p){return a(),n("div",null,[...e[0]||(e[0]=[i(`<div><h1 id="chainy-technical-design">Chainy technical design<a class="header-anchor" href="#chainy-technical-design" aria-label="Link to this section">​</a></h1><p><strong>Capstone project title:</strong> Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><p><strong>Approved scope supersession — October 8, 2026:</strong> The user selected essential fundamentals for ages 12–17, especially underserved/remote learners with limited technology access, through tappable Web3, Blockchain and AI worlds. Full A–Z coverage is withdrawn. Free spatial construction and mandatory walkable 3D/joystick navigation are deferred; use bounded order/link activities, guided three-local-replica comparison, a genuine tiny classifier validated before production, and a short fixed-grid agent. The nine lesson IDs W1–W3, B1–B3 and A1–A3 are a draft curriculum, not a confirmed count. Current baseline/GDD/curriculum take precedence over historical issue titles and old level IDs below. Phone specifications, SQLite/export, rubric and November 21 deadline remain. The old 520-hour estimate has not been recosted for this scope.</p><p>Design status: proposed implementation contract, October 5, 2026. Game source lives in <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game</a>. Requirements and decisions are maintained here. This design does not claim that any game component is implemented.</p><h2 id="architecture-and-boundaries">Architecture and boundaries<a class="header-anchor" href="#architecture-and-boundaries" aria-label="Link to this section">​</a></h2><p>Unity/C# handles presentation and game rules. SQLite stores local profiles, sessions, evidence and progress. Packaged versioned content defines activities and assessments. A small Android file-picker bridge exports an evidence package. An external staff-operated importer produces a research summary. No game backend is required.</p><figure class="diagram"><div class="mermaid-source"><pre>flowchart LR
  Learner[Learner code and touch input] --&gt; UI[Unity lesson map and activities]
  UI --&gt; Game[Mission and activity services]
  Content[Bundled versioned content] --&gt; Game
  Game --&gt; Rules[Ledger classifier and agent rules]
  Game --&gt; Save[Persistence and evidence service]
  Save --&gt; DB[(Local SQLite)]
  Staff[Teacher export screen] --&gt; Export[Consistent logical export]
  DB --&gt; Export
  Export --&gt; File[User selected package file]
  File --&gt; Transfer[Teacher controlled transfer]
  Transfer --&gt; Import[Staff importer and summary]
</pre></div><figcaption><span>Diagram</span><button class="diagram-fullscreen">Full screen ↗</button><button class="diagram-expand" aria-expanded="false">Expand diagram</button><a href="#" class="diagram-toggle">Show source</a></figcaption></figure><table><thead><tr><th>Component</th><th>Responsibility</th><th>Contract</th></tr></thead><tbody><tr><td>App/bootstrap</td><td>Validate content and database version, select profile, recover incomplete sessions</td><td>No gameplay before valid schema/profile; useful recovery screen on failure</td></tr><tr><td>Profile service</td><td>Normalize learner code and select/create local profile</td><td>Returns study/code pair; makes no verified-identity claim</td></tr><tr><td>Mission service</td><td>Objectives, checkpoint, progress and unlocks</td><td>Only validation plus persisted outcome completes a mission</td></tr><tr><td>Order/link activity service</td><td>Bounded record ordering, predecessor selection, test/revise/reset</td><td>Validate explicit causal/link rules; no free-spatial graph editor required</td></tr><tr><td>Ledger simulator</td><td>Record ordering, canonical serialization, digests, toy replica agreement</td><td>Pure deterministic results and explanatory error codes</td></tr><tr><td>Classifier service</td><td>Fit labeled feature vectors; predict held-out inputs</td><td>Deterministic prototype calculation, tie/missing-class states</td></tr><tr><td>Agent service</td><td>Step through visible policy against a grid/environment</td><td>Capped steps; reproducible trace; invalid/looping action stops safely</td></tr><tr><td>Evidence service</td><td>Record meaningful attempts and completion</td><td>Stable IDs; one transaction for result, progress and evidence</td></tr><tr><td>SQLite adapter</td><td>Parameterized operations, transaction boundaries and migration</td><td>No UI objects or Unity scene references in stored data</td></tr><tr><td>Export/import</td><td>Versioned evidence transfer and deduplication</td><td>No raw DB sharing or automatic profile-progress cloud sync</td></tr></tbody></table><p>Suggested folders in game source: Assets/Chainy/Runtime/{Core,Gameplay,Learning,Persistence,UI,Platform}, Content, Art, Audio, Scenes and Tests. Use assembly boundaries only if useful; avoid framework-building. Select a Unity LTS editor/patch and compatible lightweight render pipeline in CH-03, then pin them. SQLite binding and Android bridge are explicitly unresolved until the device spike; do not pretend a package has been selected or tested.</p><h2 id="state-and-recovery">State and recovery<a class="header-anchor" href="#state-and-recovery" aria-label="Link to this section">​</a></h2><table><thead><tr><th>State</th><th>Entry and permitted transition</th><th>Guard/recovery</th></tr></thead><tbody><tr><td>Bootstrap</td><td>Open DB; migrate; load bundled content → Profile</td><td>Failure → recovery screen; preserve old DB</td></tr><tr><td>Profile</td><td>Enter/select code → Menu</td><td>Validate format/study; a new local code creates no online account</td></tr><tr><td>Menu/world map</td><td>Select Web3, Blockchain or AI → lesson cards → introduction</td><td>Continue resolves content-versioned lesson checkpoint; missing checkpoint restarts safely</td></tr><tr><td>Guided lesson</td><td>Explanation/example → bounded activity</td><td>Pause/suspend saves a safe checkpoint; no required walkable exploration</td></tr><tr><td>Activity</td><td>Edit/test → Feedback → Retry or Quiz</td><td>Invalid arrangements explain a rule; capped loops stop</td></tr><tr><td>Quiz</td><td>Submit → Persist outcome → Summary</td><td>Disable duplicate submit; transaction failure offers retry with same event ID</td></tr><tr><td>Summary</td><td>Badge/map/next lesson</td><td>Show completion only after successful commit</td></tr><tr><td>Staff export</td><td>Select study/session scope → save package → receipt state</td><td>Cancel/write failure leaves local evidence intact</td></tr><tr><td>Suspend/exit</td><td>Persist committed checkpoints; mark interrupted session on recovery</td><td>Do not rely exclusively on application-quit callbacks</td></tr></tbody></table><p>Restart after interruption opens a new session linked to the same learner and resumes the last valid progress checkpoint. Do not alter historical attempts. Returning to a level can create a replay session; it does not overwrite the first assessment attempt.</p><h2 id="learner-identity-and-privacy-boundary">Learner identity and privacy boundary<a class="header-anchor" href="#learner-identity-and-privacy-boundary" aria-label="Link to this section">​</a></h2><p>The user&#39;s learner code proposal is adopted as <strong>offline profile identification</strong>, not authentication. A teacher-issued random code allows records from the same learner to be paired after export; it does not prove who typed it. A device label is supplementary and may change after reinstall.</p><p>Recommended procedure: teacher assigns a study ID and random uppercase code (proposed 10 unambiguous base32 characters), checks roster uniqueness, gives the code privately, and supervises session selection. An optional check character detects typing mistakes, not forgery. Do not encode names, birthdays or school IDs. A teacher may keep a separate restricted mapping where the approved study requires it; then call the dataset pseudonymous, not anonymous.</p><p>First use of a valid-format code on a device creates an empty profile after a confirmation. Later use selects that local profile. A mistyped but valid new code must show a new-profile warning. The same code on another offline device links future exported evidence but does not restore progress, verify enrollment, or detect simultaneous use automatically. No progress-transfer feature is promised.</p><p>Do not introduce password recovery or account servers for the pilot. If reliable identity verification becomes an actual requirement, stop calling this login authentication and make a separate design decision; teacher supervision and a local convenience PIN are not equivalent to remote identity verification.</p><h2 id="storage-contract">Storage contract<a class="header-anchor" href="#storage-contract" aria-label="Link to this section">​</a></h2><p>See <a href="/Chainy-Docs/attachments/docs/design/local-schema.sql">local-schema.sql</a> for an executable design schema, not a shipped migration. Use app-private internal storage through the verified Unity/Android path. Enable and verify foreign-key enforcement on every connection. <a href="https://www.sqlite.org/foreignkeys.html">SQLite documentation</a>.</p><ul><li>Study/learner identify the local profile. UUID-style random installation, session, event and export IDs are generated using a suitable random source.</li><li>Sessions bind one learner, installation and immutable build/content version.</li><li>Attempts are append-only meaningful events with ordered sequence numbers, not every frame or touch.</li><li>Progress is mutable per learner and level; it stores validated checkpoint state.</li><li>Export batches list event IDs and transfer status. An exported batch may be retried; receipt is a separate fact.</li><li>Use bound parameters and a single writer queue/short transactions. A busy database, disk-full condition or failed commit must not display false success.</li><li>Validate payload size and content IDs at the application boundary. Do not depend on SQLite JSON extensions until verified on the selected binding.</li><li>Treat device UTC timestamps as untrusted contextual data. Use monotonic elapsed duration within sessions; no claim of accurate cross-device ordering.</li><li>Default pilot data contains no names, recordings or unrestricted free-text responses. Android backup behavior must be reviewed explicitly rather than assuming no backup occurs.</li></ul><p>Android app-specific data can be removed on uninstall. A learner code alone cannot recover it. Export/backup before updates, never require uninstall, and verify migration plus signing continuity. <a href="https://developer.android.com/training/data-storage/app-specific">Android storage documentation</a>.</p><h2 id="save-and-export-sequences">Save and export sequences<a class="header-anchor" href="#save-and-export-sequences" aria-label="Link to this section">​</a></h2><p>On quiz submission generate an event ID once. Within one transaction insert the attempt, update progress if the objective is satisfied, and update the checkpoint. On failure retry using the same ID, preventing accidental double submission. Treat an existing ID with different content as a conflict.</p><p>A logical export uses a consistent read snapshot. Serialize a manifest containing schema/build/content versions, export ID, event count, selected records and integrity digest. Include the learner/study/session relationships required to interpret events. The digest detects accidental change, not malicious forgery. Export through Android&#39;s system picker; a cloud destination selected by the teacher is an external transfer choice, not a game connectivity requirement.</p><p>The importer checks schema/version, content references, size limits, uniqueness, count and integrity; rejects or quarantines malformed/conflicting records; and returns accepted/duplicate/rejected counts. Re-importing the same package must not change totals. Same learner code across installations can combine research sessions after validation; it must not overwrite progress on devices.</p><p>No record is deleted merely because a file was saved. Teacher confirms receipt and applies the approved retention policy. A canceled export creates no receipt.</p><h2 id="versioning-and-deployment">Versioning and deployment<a class="header-anchor" href="#versioning-and-deployment" aria-label="Link to this section">​</a></h2><p>Keep separate app version, schema version, content version and assessment instrument version. During an approved study, freeze content/instrument versions or stratify and explain any change. For schema migration back up consistently, migrate transactionally where supported, validate counts, and preserve recovery data on failure. Test an actual signed update on the target phone.</p><p>Christian owns builds/signing and adapter selection; Sherwin owns scope decisions; Sean owns research field definitions; Miguel owns profile/export UX. Use draft PRs for implementation, record reviewer and device evidence, and keep credentials and participant data out of both repositories.</p><h2 id="coordinated-specification-links">Coordinated specification links<a class="header-anchor" href="#coordinated-specification-links" aria-label="Link to this section">​</a></h2><p>Use the <a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">technical requirements</a> for verifiable constraints, <a href="/Chainy-Docs/content/docs/design/app-flow.html">app flow</a> for the detailed state/guard/recovery table, and <a href="/Chainy-Docs/content/docs/design/database-schema.html">database schema reference</a> alongside the canonical SQL. The <a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">parallel implementation plan</a> assigns contract ownership and integration gates. These documents expand this architecture rather than selecting an untested Unity version or SQLite adapter.</p><h2 id="revised-content-catalog-boundary">Revised content catalog boundary<a class="header-anchor" href="#revised-content-catalog-boundary" aria-label="Link to this section">​</a></h2><p>World IDs identify Web3, Blockchain and AI. Lesson IDs and their activity IDs are versioned content, with W1–W3/B1–B3/A1–A3 currently a draft. Existing SQLite <code>level_id</code> remains a text lesson-progress key; see the database contract for explicit legacy content mapping. Do not silently reuse an old level completion for newly split lessons, rename historical evidence, or require a destructive schema reset. Curriculum expansion/reduction changes content/version and reviewed prerequisites, not a hard-coded lesson count.</p></div>`,1)])])}const m=t(r,[["render",s]]);export{h as __pageData,m as default};
